$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$Project = 'C:\shabashka_app'
$BackupRoot = 'C:\shabashka_backups'
$Stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$Backup = Join-Path $BackupRoot ('package8_' + $Stamp)
New-Item -ItemType Directory -Force -Path $Backup | Out-Null
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false, $true)
function Decode-B64([string]$Value) { return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value)) }
function Get-Sha256([string]$Path) { return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant() }
function Replace-Exactly([string]$Text, [string]$Old, [string]$New, [string]$Label) { $Count = ([regex]::Matches($Text, [regex]::Escape($Old))).Count; if ($Count -ne 1) { throw ($Label + ': expected 1 match, got ' + $Count) }; return $Text.Replace($Old, $New) }
$Plans = @()
$Patches0 = @()
$Patches0 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Patches0 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Patches0 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Patches0 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Patches0 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Patches0 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Patches0 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Plans += [pscustomobject]@{ Rel = 'lib\providers\job_provider.dart'; OldSha = '7c1da117f9282ee63ddcbedcf3bcb56faaaf3049f0b6a9b5577e04dab6bf18f0'; NewSha = 'bade19bf893898d6ce8c1eea03fb7d6521360896780f9f99be104f8cbcada9a5'; Patches = $Patches0 }
$Patches1 = @()
$Patches1 += [pscustomobject]@{ Old = Decode-B64 ''; New = Decode-B64 '' }
$Plans += [pscustomobject]@{ Rel = 'lib\models\performer.dart'; OldSha = 'cbb4d1fcd9a441f8c0db4cc3ba9589e2fdc5d623662474c5e87ca7d86c15ab04'; NewSha = '626631c5c7e9a6941583382a287f3c0a957b4b17234ac496a6cceadd98e846f7'; Patches = $Patches1 }
$Prepared = @()
try {
  foreach ($Plan in $Plans) {
    $Path = Join-Path $Project $Plan.Rel
    if (-not (Test-Path -LiteralPath $Path)) { throw ('Missing file: ' + $Path) }
    $Actual = Get-Sha256 $Path
    if ($Actual -ne $Plan.OldSha) { throw ($Plan.Rel + ': source SHA mismatch. Expected ' + $Plan.OldSha + ', got ' + $Actual) }
    $BackupFile = Join-Path $Backup ($Plan.Rel.Replace('\','_'))
    Copy-Item -LiteralPath $Path -Destination $BackupFile -Force
    $Text = [IO.File]::ReadAllText($Path, $Utf8NoBom)
    $Number = 0
    foreach ($Patch in $Plan.Patches) { $Number++; $Text = Replace-Exactly $Text $Patch.Old $Patch.New ($Plan.Rel + ' patch ' + $Number) }
    if ($Text.Contains([char]0xFFFD)) { throw ($Plan.Rel + ': U+FFFD detected') }
    $Temp = $Path + '.package8.tmp'
    [IO.File]::WriteAllText($Temp, $Text, $Utf8NoBom)
    if ((Get-Sha256 $Temp) -ne $Plan.NewSha) { throw ($Plan.Rel + ': target SHA mismatch') }
    $Prepared += [pscustomobject]@{ Path=$Path; Temp=$Temp; Backup=$BackupFile }
  }
  foreach ($Item in $Prepared) { Move-Item -LiteralPath $Item.Temp -Destination $Item.Path -Force }
} catch { foreach ($Item in $Prepared) { if (Test-Path -LiteralPath $Item.Temp) { Remove-Item -LiteralPath $Item.Temp -Force -ErrorAction SilentlyContinue }; if (Test-Path -LiteralPath $Item.Backup) { Copy-Item -LiteralPath $Item.Backup -Destination $Item.Path -Force -ErrorAction SilentlyContinue } }; throw }
Write-Host ('Backup: ' + $Backup)
foreach ($Plan in $Plans) { Write-Host ($Plan.Rel + ' SHA256=' + (Get-Sha256 (Join-Path $Project $Plan.Rel))) }
Write-Host 'PACKAGE8_PRIVATE_STATE_APPLIED_OK'
Write-Host 'Next: flutter analyze'
